import os
import boto3
from botocore.exceptions import ClientError

def normalize_expense(payload, config=None):
    config = config or {}
    client = boto3.client('textract', region_name=config.get('aws_region', 'us-east-1'))
    try:
        if isinstance(payload, dict) and 'S3Object' in payload:
            response = client.analyze_expense(Document=payload)
        else:
            response = client.analyze_expense(Document={'Bytes': payload})
        normalized = {
            'vendor_name': None,
            'total_amount': None,
            'tax_amount': None,
            'date': None,
            'currency': 'USD'
        }
        for expense_doc in response.get('ExpenseDocuments', []):
            for summary_field in expense_doc.get('SummaryFields', []):
                label = summary_field.get('LabelDetection', {}).get('Text', '').lower()
                value_text = summary_field.get('ValueDetection', {}).get('Text', '')
                if 'vendor' in label or 'name' in label:
                    normalized['vendor_name'] = value_text
                elif 'total' in label:
                    normalized['total_amount'] = float(value_text.replace('$', '').replace(',', '')) if value_text else None
                elif 'tax' in label:
                    normalized['tax_amount'] = float(value_text.replace('$', '').replace(',', '')) if value_text else None
                elif 'date' in label:
                    normalized['date'] = value_text
                if value_text and '$' in value_text:
                    normalized['currency'] = 'USD'
        result = normalized
    except ClientError as e:
        result = {'error': str(e)}
    return result
